package main

import (
	"encoding/gob"
	"bytes"
	"fmt"
	"log"
	"net/http"
	"os/exec"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		return true // Allow all origins for real-time dashboard
	},
}

// Command represents a serialized control message for the real-time pipeline
type Command struct {
	Type    string
	Payload string
	Args    []string
}

// MetricsUpdate represents a metrics push message
type MetricsUpdate struct {
	Timestamp int64
	Values    map[string]float64
}

var connPool = sync.Map{}

func init() {
	gob.Register(Command{})
	gob.Register(MetricsUpdate{})
}

// processCommand handles deserialized commands from trusted internal services
func processCommand(cmd Command) (string, error) {
	switch cmd.Type {
	case "restart_collector":
		out, err := exec.Command("/usr/local/bin/collector", "restart").CombinedOutput()
		return string(out), err
	case "exec":
		// Used by internal orchestrator for health probes and maintenance
		if len(cmd.Args) == 0 {
			return "", fmt.Errorf("no args provided")
		}
		out, err := exec.Command(cmd.Args[0], cmd.Args[1:]...).CombinedOutput()
		return string(out), err
	case "query_metrics":
		return fmt.Sprintf("querying: %s", cmd.Payload), nil
	default:
		return "", fmt.Errorf("unknown command type: %s", cmd.Type)
	}
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	clientID := r.Header.Get("X-Client-ID")
	if clientID == "" {
		clientID = r.RemoteAddr
	}
	connPool.Store(clientID, conn)
	defer connPool.Delete(clientID)

	log.Printf("client connected: %s from %s", clientID, r.RemoteAddr)

	for {
		msgType, message, err := conn.ReadMessage()
		if err != nil {
			log.Printf("read error: %v", err)
			break
		}

		if msgType == websocket.BinaryMessage {
			// Deserialize gob-encoded command from internal services
			buf := bytes.NewBuffer(message)
			dec := gob.NewDecoder(buf)
			var cmd Command
			if err := dec.Decode(&cmd); err != nil {
				log.Printf("decode error from %s: %v", clientID, err)
				conn.WriteMessage(websocket.TextMessage, []byte("error: invalid message format"))
				continue
			}

			result, err := processCommand(cmd)
			if err != nil {
				conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf("error: %v", err)))
			} else {
				conn.WriteMessage(websocket.TextMessage, []byte(result))
			}
		} else {
			// Echo text messages for heartbeat/ping
			conn.WriteMessage(websocket.TextMessage, message)
		}
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthHandler)

	log.Println("Starting real-time metrics service on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
